    if r<0.45: return 'while '+expr(d-1)+'; '+stmt(d-1)+'; end'
    if r<0.55: return 'until '+expr(d-1)+'; '+stmt(d-1)+'; end'
    if r<0.65: return 'break '+expr(d-1)
    if r<0.75: return 'next '+expr(d-1)
    if r<0.85: return expr(d-1)
    return stmt(d-1)+'; '+stmt(d-1)

def program():
    parts=[]
    if random.random()<0.4:
        args=[]
        for i in range(random.randint(0,4)):
            name=random.choice(vars)
            if random.random()<0.6: args.append(name+'='+expr(2))
            else: args.append(name)
        parts.append('def m('+','.join(args)+'); '+stmt(3)+'; end')
    parts.append(stmt(4))
    return '\n'.join(parts)+'\n'

