import subprocess, os, sys, base64, concurrent.futures
N=int(sys.argv[1]) if len(sys.argv)>1 else 200

def one(i):
    src=subprocess.check_output(['python3','/workspace/fuzz/fuzzgen.py',str(i)], text=True)
    b=base64.b64encode(src.encode()).decode()
    cmd=f"echo {b} | base64 -d >/tmp/f{i}.rb; ASAN_OPTIONS=detect_leaks=0:symbolize=0 build/host/bin/mruby /tmp/f{i}.rb"
    try:
        r=subprocess.run(['bash','/workspace/build.sh',cmd],text=True,stdout=subprocess.PIPE,stderr=subprocess.STDOUT,timeout=20)
        out=r.stdout
    except subprocess.TimeoutExpired:
        return None
    if 'ERROR: AddressSanitizer' in out or 'heap-buffer-overflow' in out or 'use-after-free' in out:
        open(f'/workspace/fuzz/crash_{i}.rb','w').write(src); open(f'/workspace/fuzz/crash_{i}.out','w').write(out); return (i,src,out[-2000:])
    if i%50==0: print('done',i,flush=True)
    return None
for i in range(N):
    res=one(i)
    if res:
        print('CRASH',res[0]); print(res[1]); print(res[2]); sys.exit(0)
